static CharacterToken cpp_tokenize_body(const std::string& body,const std::vector<blink_entity_semantics::Entity>& entities){
  CharacterToken token;
  for(size_t i=0;i<body.size()&&body[i]!='<';){
    if(body[i]=='&'){
      bool decoded=false;
      const blink_entity_semantics::Entity* best=nullptr;
      for(const auto& entity:entities)if(entity.name.size()>(best?best->name.size():0)&&body.compare(i+1,entity.name.size(),entity.name)==0)best=&entity;
      if(best){
        for(unsigned unit:blink_entity_semantics::utf16_units(best->first_value))token.data.push_back(static_cast<char16_t>(unit));
        if(best->second_value)for(unsigned unit:blink_entity_semantics::utf16_units(*best->second_value))token.data.push_back(static_cast<char16_t>(unit));
        token.has_entity=true;i+=best->name.size()+1;decoded=true;
      }
      for(const auto& [name,value]:body_reference_entities) if(!decoded&&body.compare(i+1,name.size(),name)==0){
        token.data.append(value);token.has_entity=true;i+=name.size()+1;decoded=true;break;
      }
      if(decoded)continue;
      token.data.push_back('&');++i;continue;
    }
    token.data.push_back(body[i++]);
  }
  return token;
}
